TEST(PartSets, GroupedByReleaseAndHostNeverByAdjacency)
{
    // Rootz parts interleaved with another host, a single mirror, and a restart.
    const std::vector<ParsedLink> links = {
        pl(0, "USA 12.xx Base - Rootz part 1", "rootz.so"),
        pl(1, "USA 12.xx Base - Akirabox part 1", "akirabox.com"),
        pl(2, "USA 12.xx Base - Rootz part 2", "rootz.so"),
        pl(3, "USA 12.xx Base - Akirabox part 2", "akirabox.com"),
        pl(4, "USA 12.xx Base - 1fichier", "1fichier.com"),
        pl(5, "USA 12.xx Base - Rootz part 3", "rootz.so"),
        pl(6, "EUR 12.xx Base - Rootz part 1", "rootz.so"),
    };
    const PartGrouping g = group_parts(links);
    ASSERT_EQ(g.sets.size(), 3u);
    EXPECT_EQ(g.singles, (std::vector<int>{4}));
    EXPECT_EQ(g.sets[0].host, "Rootz");
    EXPECT_EQ(g.sets[0].links, (std::vector<int>{0, 2, 5}));
    EXPECT_EQ(g.sets[0].status, PartStatus::complete);
    EXPECT_EQ(g.sets[0].range_text(), "1\xE2\x80\x93" "3");
    EXPECT_EQ(g.sets[1].host, "Akirabox");
    EXPECT_EQ(g.sets[1].links, (std::vector<int>{1, 3}));
    EXPECT_EQ(g.sets[2].links, (std::vector<int>{6})); // another release: its own set
    // Download all parts: catalogue order, skipping what is already queued.
    EXPECT_EQ(parts_to_queue(g.sets[0], links), (std::vector<int>{0, 2, 5}));
    EXPECT_EQ(parts_to_queue(g.sets[0], links, [](int i) { return i == 2; }), (std::vector<int>{0, 5}));
}

TEST(PartSets, RestartsGapsAndCutNumbersAreReported)
{
    const std::vector<ParsedLink> restart = {
        pl(0, "EUR 9.xx Base - Vikingfile part 1", "vikingfile.com"),
        pl(1, "EUR 9.xx Base - Vikingfile part 2", "vikingfile.com"),
        pl(2, "EUR 9.xx Base - Vikingfile part 1", "vikingfile.com"),
    };
    PartGrouping g = group_parts(restart);
    ASSERT_EQ(g.sets.size(), 1u);
    EXPECT_EQ(g.sets[0].status, PartStatus::restarts);
    EXPECT_EQ(g.sets[0].runs.size(), 2u);
    EXPECT_EQ(g.sets[0].range_text(), "1\xE2\x80\x93" "2, 1");

    const std::vector<ParsedLink> gaps = {
        pl(0, "EUR 9.xx Base - Akirabox part 1", "akirabox.com"),
        pl(1, "EUR 9.xx Base - Akirabox part 2", "akirabox.com"),
        pl(2, "EUR 9.xx Base - Akirabox part 3", "akirabox.com"),
        pl(3, "EUR 9.xx Base - Akirabox part 5", "akirabox.com"),
    };
    g = group_parts(gaps);
    ASSERT_EQ(g.sets.size(), 1u);
    EXPECT_EQ(g.sets[0].status, PartStatus::gaps);
    EXPECT_EQ(g.sets[0].missing(), (std::vector<int>{4}));

    // 63-byte names: numbers cut off, numbered by position; identical cut names repeat.
    const std::vector<ParsedLink> cut = {
        pl(0, "USA 12.xx Game (v01.004.003) [APR-EMU] [ ALL DLC ] - Mediafire ", "mediafire.com"),
        pl(1, "USA 12.xx Game (v01.004.003) [APR-EMU] [ ALL DLC ] - Mediafire ", "mediafire.com"),
        pl(2, "USA 12.xx Game (v01.004.003) [APR-EMU] [ ALL DLC ] - Mediafire ", "mediafire.com"),
    };
    g = group_parts(cut);
    ASSERT_EQ(g.sets.size(), 1u);
    EXPECT_EQ(g.sets[0].status, PartStatus::unnumbered);
    EXPECT_EQ(g.sets[0].numbers, (std::vector<int>{1, 2, 3}));
    // A single cut name is a single link.
    g = group_parts({cut[0]});
    EXPECT_TRUE(g.sets.empty());
    EXPECT_EQ(g.singles.size(), 1u);
}

// ---- synthetic packages ----

PackageLink plink(int index, const char *name, const char *host, LinkRoute route = LinkRoute::capture,
                 const char *provider = "", const char *url = "")
{
    PackageLink l;
    l.index = index;
    l.name = name;
    l.host = host;
    l.route = route;
    l.provider = provider;
    l.url = url;
    l.needs_browser = route == LinkRoute::capture || route == LinkRoute::browser_only;
    return l;
}

PackageDetail detail(const char *id, const char *title, const char *source, std::vector<PackageLink> links,
                     double size = 0.0, const char *version = "")
{
    PackageDetail d;
    d.package.id = id;
    d.package.title = title;
    d.package.source_name = source;
    d.package.size_bytes = size;
    d.package.version = version;
    d.package.link_count = static_cast<int>(links.size());
    d.links = std::move(links);
    return d;
}

Package package(const char *id, const char *title, const char *title_id, const char *source = "S",
                const char *description = "")
{
    Package p;
    p.id = id;
    p.title = title;
    p.title_id = title_id;
    p.source_name = source;
    p.description = description;
    p.link_count = 1;
    return p;
}

