TEST(GameGroup, SplitsOnEvidenceAndJoinsRegionsByTitle)
{
    const std::vector<Package> p = {
        package("1", "Turok", "PPSA24558"),
        package("2", "Turok Trilogy Bundle", "PPSA24558"),
        package("3", "Turok 2 Seeds of Evil", "PPSA24560"),
        package("4", "Turok Trilogy Bundle", "PPSA24560"),
        package("5", "F1 25", "PPSA24662"),
        package("6", "No Sleep For Kaname Date", "PPSA24662"),
        package("7", "Wo Long Fallen Dynasty", "PPSA08772", "DLPS", "Region: USA"),
        package("8", "[exFAT] Wo Long: Fallen Dynasty", "PPSA08773", "DLPS", "Region: EUR"),
        package("9", "Some Game Demo", "PPSA00001"),
        package("10", "Some Game", "PPSA00001"),
        package("11", "UFC 5", "PPSA00002"),
        package("12", "EA Sports UFC 5", "PPSA00002"),
    };
    const GameIndex index = group_games(p);
    const auto same = [&](int a, int b) { return index.game_of[static_cast<std::size_t>(a)] == index.game_of[static_cast<std::size_t>(b)]; };
    EXPECT_FALSE(same(0, 1)); // bundle word
    EXPECT_TRUE(same(1, 3));  // the bundle listed under two ids is one game
    EXPECT_FALSE(same(0, 2)); // Turok / Turok 2
    EXPECT_FALSE(same(4, 5)); // wrong id, no shared word
    EXPECT_TRUE(same(6, 7));  // two regions, one game
    EXPECT_FALSE(same(8, 9)); // demo guard
    EXPECT_TRUE(same(10, 11)); // same id, shared words, same numbers
    const GameGroup &wo = index.games[static_cast<std::size_t>(index.game_of[6])];
    EXPECT_EQ(wo.id, "g:wolongfallendynasty");
    EXPECT_EQ(wo.title_ids, (std::vector<std::string>{"PPSA08772", "PPSA08773"}));
    EXPECT_EQ(wo.regions, (std::vector<std::string>{"USA", "EUR"}));
    EXPECT_EQ(wo.title, "Wo Long: Fallen Dynasty"); // a tie: the one with punctuation
    // The id does not depend on the order of the catalogue.
    std::vector<Package> reversed(p.rbegin(), p.rend());
    const GameIndex again = group_games(reversed);
    std::set<std::string> a;
    std::set<std::string> b;
    for (const GameGroup &g : index.games)
        a.insert(g.id);
    for (const GameGroup &g : again.games)
        b.insert(g.id);
    EXPECT_EQ(a, b);
    // The review list names the splits and the cross-id joins.
    const std::vector<ReviewItem> review = review_list(p, index);
    int splits = 0;
    int joins = 0;
    for (const ReviewItem &r : review)
        (r.kind == ReviewItem::Kind::split ? splits : joins) += 1;
    EXPECT_EQ(splits, 4); // PPSA24558, PPSA24560, PPSA24662, PPSA00001
    EXPECT_EQ(joins, 2);  // Wo Long, Turok Trilogy Bundle
}

