TEST(Ranking, TooNewIsLastAndPreferencesReorder)
{
    std::vector<Candidate> c(4);
    c[0].tier = LinkTier::debrid;
    c[0].fw = "12.xx";
    c[0].region = "USA";
    c[1].tier = LinkTier::supported;
    c[1].fw = "4.xx";
    c[1].backport = true;
    c[1].region = "EUR";
    c[1].index = 1;
    c[2].tier = LinkTier::automated;
    c[2].region = "EUR";
    c[2].parts = 3;
    c[2].status = PartStatus::complete;
    c[2].index = 2;
    c[3].tier = LinkTier::native_pkg;
    c[3].fw = "13.xx";
    c[3].index = 3;
    LinkPrefs prefs;
    prefs.firmware = "10.xx";
    Ranking r = rank_links(c, prefs);
    // native .pkg needs 13.xx: last; debrid needs 12.xx: too new as well.
    EXPECT_EQ(r.order, (std::vector<int>{2, 1, 3, 0}));
    EXPECT_EQ(r.too_new, 2);
    EXPECT_EQ(r.summary(" - "), "Automatic - EUR - 3 parts");
    EXPECT_EQ(r.why, "Pegasus fetches it by itself, firmware not stated");
    // No firmware set: native first, then debrid.
    prefs.firmware.clear();
    r = rank_links(c, prefs);
    EXPECT_EQ(r.order, (std::vector<int>{3, 0, 2, 1}));
    // Prefer debrid off: automated before debrid, debrid before browser.
    prefs.prefer_debrid = false;
    r = rank_links(c, prefs);
    EXPECT_EQ(r.order, (std::vector<int>{3, 2, 0, 1}));
    // Hidden hosts are never offered.
    for (Candidate &x : c)
        x.host = "H" + std::to_string(x.index);
    prefs.hidden_hosts = {"H3"};
    r = rank_links(c, prefs);
    EXPECT_EQ(r.order.size(), 3u);
    EXPECT_EQ(r.best, 2);
    // Region and format preferences inside one tier; fewer parts; known size; newer version.
    std::vector<Candidate> same(4);
    for (int i = 0; i < 4; ++i)
    {
        same[static_cast<std::size_t>(i)].tier = LinkTier::supported;
        same[static_cast<std::size_t>(i)].index = i;
    }
    same[0].region = "EUR";
    same[1].region = "USA";
    same[1].parts = 4;
    same[1].status = PartStatus::complete;
    same[2].region = "USA";
    same[2].version = "01.002";
    same[3].region = "USA";
    same[3].version = "01.010";
    same[2].format = LinkFormat::exfat;
    LinkPrefs p2;
    p2.region = "USA";
    EXPECT_EQ(rank_links(same, p2).order, (std::vector<int>{3, 2, 1, 0}));
    p2.format = LinkFormat::exfat;
    EXPECT_EQ(rank_links(same, p2).order, (std::vector<int>{2, 3, 1, 0}));
    EXPECT_TRUE(rank_links({}, p2).text().empty());
}

