// ---- the recorded catalogue ----

std::string samples_dir()
{
    if (const char *env = std::getenv("WINGS_SAMPLES"))
        return env;
    return std::string(HUI_SOURCE_DIR) + "/../../recon/samples";
}

bool read_sample(const std::string &name, std::string *out)
{
    std::ifstream file(samples_dir() + "/" + name, std::ios::binary);
    if (!file)
        return false;
    std::ostringstream text;
    text << file.rdbuf();
    *out = text.str();
    return true;
}

double seconds_since(std::chrono::steady_clock::time_point start)
{
    return std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
}

TEST(LinksLibrary, TheWholeRecordedCatalogueMatchesTheResearch)
{
    std::string library;
    if (!read_sample("library.json", &library))
        GTEST_SKIP() << "recon/samples/library.json is not reachable from here";
    auto replay = std::make_shared<wings::http::ReplayTransport>();
    replay->add("GET", "/api/health", 200,
                R"({"status":"running","port":6970,"downloadOnly":false,"nativePkgHandoff":true,"version":"1.11.0"})");
    replay->add("GET", "/api/library", 200, library);
    PegasusBackend backend(replay, "127.0.0.1:6970");
    const Result<std::vector<Package>> all = backend.library();
    ASSERT_TRUE(all.ok());
    ASSERT_EQ(all.value.size(), 2962u);
    std::vector<PackageDetail> details;
    details.reserve(all.value.size());
    for (const Package &p : all.value)
    {
        const Result<PackageDetail> d = backend.package(p.id);
        ASSERT_TRUE(d.ok());
        details.push_back(d.value);
    }

    // 1. Every link parses; coverage equals the research's section 1.6.
    const auto t_parse = std::chrono::steady_clock::now();
    long links = 0, host = 0, region = 0, fw = 0, part = 0, version = 0, format = 0, explicit_kind = 0;
    long residue = 0, wrapped = 0;
    std::map<PartStatus, long> sets;
    long set_count = 0;
    std::vector<std::vector<ParsedLink>> parsed(details.size());
    for (std::size_t i = 0; i < details.size(); ++i)
    {
        parsed[i] = parse_links(details[i].links);
        for (const ParsedLink &l : parsed[i])
        {
            const LinkMeta &f = l.meta;
            ++links;
            host += f.host.empty() ? 0 : 1;
            region += f.region.empty() ? 0 : 1;
            fw += f.min_fw().empty() ? 0 : 1;
            part += f.has_part() ? 1 : 0;
            version += f.version.empty() ? 0 : 1;
            format += f.format == LinkFormat::none ? 0 : 1;
            explicit_kind += f.kind_inferred ? 0 : 1;
            residue += f.residue.empty() ? 0 : 1;
            wrapped += f.wrapped ? 1 : 0;
        }
        for (const PartSet &s : group_parts(parsed[i]).sets)
        {
            ++sets[s.status];
            ++set_count;
        }
    }
    const double parse_seconds = seconds_since(t_parse);
    std::printf("[links] %ld links: host %ld region %ld fw/bp %ld part %ld version %ld format %ld kind %ld "
                "residue %ld wrapped %ld; %ld sets (complete %ld restarts %ld gaps %ld unnumbered %ld) in %.2f s\n",
                links, host, region, fw, part, version, format, explicit_kind, residue, wrapped, set_count,
                sets[PartStatus::complete], sets[PartStatus::restarts], sets[PartStatus::gaps],
                sets[PartStatus::unnumbered], parse_seconds);
    EXPECT_EQ(links, 35559);
    EXPECT_EQ(host, 35559);
    EXPECT_EQ(region, 27061);
    EXPECT_EQ(fw, 23624);
    EXPECT_EQ(part, 18727);
    EXPECT_EQ(version, 5750);
    EXPECT_EQ(format, 5503);
    EXPECT_EQ(explicit_kind, 35559 - 10083);
    EXPECT_EQ(residue, 0);
    EXPECT_EQ(set_count, 4227);
    EXPECT_EQ(sets[PartStatus::complete], 3944);
    EXPECT_EQ(sets[PartStatus::restarts], 225);
    EXPECT_EQ(sets[PartStatus::unnumbered], 30);
    EXPECT_EQ(sets[PartStatus::gaps], 28);

    // 2. Grouping: 1,084 games over the 2,945 packages with links, 222 cross-id
    // games, 26 split titleIds, none of the known bad merges.
    const auto t_group = std::chrono::steady_clock::now();
    std::vector<Package> games_in;
    std::vector<std::size_t> detail_of;
    for (std::size_t i = 0; i < all.value.size(); ++i)
    {
        if (all.value[i].link_count > 0)
        {
            games_in.push_back(all.value[i]);
            detail_of.push_back(i);
        }
    }
    EXPECT_EQ(games_in.size(), 2945u);
    const GameIndex index = group_games(games_in);
    const std::vector<ReviewItem> review = review_list(games_in, index);
    const double group_seconds = seconds_since(t_group);
    long splits = 0, joins = 0;
    for (const ReviewItem &r : review)
        (r.kind == ReviewItem::Kind::split ? splits : joins) += 1;
    std::printf("[games] %zu games, %ld cross-titleId joins, %ld split titleIds in %.2f s\n", index.games.size(),
                joins, splits, group_seconds);
    EXPECT_EQ(index.games.size(), 1084u);
    EXPECT_EQ(joins, 222);
    EXPECT_EQ(splits, 26);
    std::set<std::string> ids;
    for (const GameGroup &g : index.games)
        ids.insert(g.id);
    EXPECT_EQ(ids.size(), index.games.size()); // game ids are unique
    const auto game_with = [&](const char *title)
    {
        for (std::size_t i = 0; i < games_in.size(); ++i)
            if (games_in[i].title == title)
                return index.game_of[i];
        ADD_FAILURE() << "no package titled " << title;
        return -1;
    };
    const int gta3 = game_with("Grand Theft Auto III The Definitive Edition");
    const int sa = game_with("Grand Theft Auto San Andreas The Definitive Edition");
    const int vc = game_with("Grand Theft Auto Vice City The Definitive Edition");
    const int trilogy = game_with("Grand Theft Auto The Trilogy The Definitive Edition");
    EXPECT_EQ(std::set<int>({gta3, sa, vc, trilogy}).size(), 4u);
    EXPECT_EQ(gta3, game_with("Grand Theft Auto 3 The Definitive Edition"));
    const int t1 = game_with("Turok");
    const int t2 = game_with("Turok 2 Seeds of Evil");
    const int t3 = game_with("Turok 3 Shadow of Oblivion");
    const int tb = game_with("Turok Trilogy Bundle");
    EXPECT_EQ(std::set<int>({t1, t2, t3, tb}).size(), 4u);
    EXPECT_EQ(index.games[static_cast<std::size_t>(tb)].title_ids.size(), 3u);

    // 3. Every game page builds, ranks and filters.
    const auto t_pages = std::chrono::steady_clock::now();
    long releases = 0, mirrors = 0, shown = 0, duplicates = 0, with_best = 0;
    LinkPrefs prefs;
    prefs.firmware = "10.xx";
    prefs.region = "USA";
    for (const GameGroup &g : index.games)
    {
        std::vector<PackageDetail> d;
        for (const int p : g.packages)
            d.push_back(details[detail_of[static_cast<std::size_t>(p)]]);
        GamePage page = build_game_page(d);
        rank_page(&page, prefs);
        const Facets f = page_facets(page, prefs);
        MirrorFilter filter;
        filter.runs_on_my_fw = true;
        const FilterResult r = filter_mirrors(page, filter, prefs);
        EXPECT_EQ(static_cast<int>(r.mirrors.size()) + r.hidden_too_new <= f.total, true);
        releases += static_cast<long>(page.releases.size());
        mirrors += static_cast<long>(page.mirrors.size());
        shown += page.unique_links;
        duplicates += page.duplicate_links;
        with_best += page.best >= 0 ? 1 : 0;
        for (int m = 0; m < static_cast<int>(page.mirrors.size()); ++m)
            EXPECT_FALSE(page.queue_refs(m).empty());
    }
    const double page_seconds = seconds_since(t_pages);
    std::printf("[pages] %ld releases, %ld mirrors, %ld links shown, %ld duplicate copies hidden, "
                "%ld games with a Best in %.2f s\n",
                releases, mirrors, shown, duplicates, with_best, page_seconds);
    EXPECT_EQ(shown + duplicates, 35559);
    EXPECT_LE(duplicates, 1415); // URL copies inside a game (research 3.4); set parts are never hidden
    EXPECT_GT(duplicates, 1000);
    // Bounds under the sanitizers (the console runs this only on change, per game).
    EXPECT_LT(parse_seconds, 10.0);
    EXPECT_LT(group_seconds, 5.0);
    EXPECT_LT(page_seconds, 20.0);
}

